export const PURPOSE_SET = new Set(PURPOSES.map((p) => p.key.toLowerCase()))
export const isPurposeTag = (tag: string) => PURPOSE_SET.has(tag.trim().toLowerCase())
export const purposeIcon = (key: string) =>
  PURPOSES.find((p) => p.key.toLowerCase() === key.toLowerCase())?.icon || '✦'

// ── Cover images ──────────────────────────────────────────────────────────
// Fill these in to show a custom cover per crystal / purpose (like the
// reference site). Any not listed here fall back to a representative product
// photo automatically. Keys are matched case-insensitively.
// Example:  'Amethyst': 'https://your-cdn/amethyst.jpg',
export const CRYSTAL_IMAGES: Record<string, string> = {
  // 'Amethyst': '',
}
export const PURPOSE_IMAGES: Record<string, string> = {
  // 'Abundance & Wealth': '',
}
export const coverFor = (
  map: Record<string, string>, name: string,
): string | undefined => {
  const hit = Object.keys(map).find((k) => k.toLowerCase() === name.toLowerCase())
  return hit ? map[hit] : undefined
}

// ── S3 / CDN cover images ─────────────────────────────────────────
// Set CRYSTAL_IMAGE_BASE once to the S3/CloudFront folder your crystal PNGs
// live in (NO trailing slash), e.g.
//   export const CRYSTAL_IMAGE_BASE =
//     'https://your-bucket.s3.ap-south-1.amazonaws.com/crystals'
// The objects must be publicly readable over HTTPS (bucket policy or
// CloudFront) — not pre-signed URLs. Leave '' to keep product-photo fallbacks.
// Each cover resolves to  <base>/<exact filename>  from CRYSTAL_COVER_FILES.
// Any crystal without a file quietly falls back to a product photo.
export const CRYSTAL_IMAGE_BASE = 'https://thecosmicconnect-crystal-cover-images.s3.ap-south-1.amazonaws.com'

