export function crystalCoverUrl(name: string): string {
  const override = coverFor(CRYSTAL_IMAGES, name)
  if (override) return override
  const file =
    CRYSTAL_COVER_FILES[name] ||
    Object.entries(CRYSTAL_COVER_FILES).find(([k]) => k.toLowerCase() === name.toLowerCase())?.[1]
  if (!file || !CRYSTAL_IMAGE_BASE) return ''
  // Covers are uploaded as optimized .webp (see optimize_covers.py)
  const webp = file.replace(/\.png$/i, '.webp')
  return `${CRYSTAL_IMAGE_BASE}/${encodeURIComponent(webp)}`
}

// Same idea for purpose covers (optional — leave base '' to use product photos).
export const PURPOSE_IMAGE_BASE = ''
export const PURPOSE_IMAGE_EXT = 'png'
export function purposeCoverUrl(key: string): string {
  const override = coverFor(PURPOSE_IMAGES, key)
  if (override) return override
  return PURPOSE_IMAGE_BASE ? `${PURPOSE_IMAGE_BASE}/${toSlug(key)}.${PURPOSE_IMAGE_EXT}` : ''
}
